var batteryProfiles=engine&&engine.batteryProfiles?engine.batteryProfiles:{none:{label:"No battery",costFactor:.75,generatorFactor:.18},starter:{label:"Starter backup",costFactor:.9,generatorFactor:.45},essential:{label:"Essential loads",costFactor:1,generatorFactor:.7},extended:{label:"Extended backup",costFactor:1.25,generatorFactor:.88}};
function byId(id){return document.getElementById(id);}
function num(id,fallback){var el=byId(id);var value=el?parseFloat(el.value):NaN;return Number.isFinite(value)?value:(fallback||0);}
function val(id){var el=byId(id);return el?el.value:"";}
function normalizeCountry(value){return String(value||"").trim().toLowerCase();}
function findCountry(value){var query=normalizeCountry(value);if(!query)return null;return SOLAR_COUNTRIES.filter(function(country){return normalizeCountry(country.slug)===query||normalizeCountry(country.code)===query||normalizeCountry(country.name)===query||normalizeCountry(country.currency)===query;})[0]||SOLAR_COUNTRIES.filter(function(country){return normalizeCountry(country.name).indexOf(query)>=0||normalizeCountry(country.slug).indexOf(query)>=0||normalizeCountry(country.currency).indexOf(query)>=0||normalizeCountry(country.code).indexOf(query)>=0;})[0]||null;}
function storeSelectedCountry(country){if(!country)return;try{localStorage.setItem(COUNTRY_STORAGE_KEY,country.code);}catch(error){}}
function updateCountryQuery(country){if(!country||!history.replaceState)return;try{var url=new URL(location.href);url.searchParams.set("country",country.code);history.replaceState(null,"",url.toString());}catch(error){}}
function setupCountryPicker(prefix,currentSlug){
  var input=byId(prefix+"Search");var select=byId(prefix+"Select");var open=byId(prefix+"Open");var status=byId(prefix+"Status");if(!select||!open||!status)return;
  var current=findCountry(currentSlug)||findCountry(DEFAULTS.countryCode)||SOLAR_COUNTRIES[0];
  function apply(country,updateUrl){if(!country)return;select.value=country.slug;if(input)input.value=country.name;open.href=country.href;open.textContent="Open "+country.name+" calculator";status.textContent=country.flag+" "+country.name+" selected - "+country.currency;if(select.closest("[data-solar-country-picker]"))select.closest("[data-solar-country-picker]").setAttribute("data-selected-country",country.slug);storeSelectedCountry(country);if(updateUrl)updateCountryQuery(country);}
  var params=new URLSearchParams(location.search);var initial=findCountry(params.get("country"))||findCountry(currentSlug)||current;apply(initial,false);
  if(input){input.addEventListener("input",function(){var match=findCountry(input.value);if(match){apply(match,true);}else{status.textContent="No exact country match yet. Keep typing or use the dropdown.";}});input.addEventListener("keydown",function(event){if(event.key==="Enter"){var match=findCountry(input.value)||findCountry(select.value);if(match){event.preventDefault();apply(match,true);location.href=match.href;}}});}
  select.addEventListener("change",function(){var country=findCountry(select.value);apply(country,true);trackSolarEvent("country_selected","country_picker",country?country.slug:DEFAULTS.countrySlug);});
  open.addEventListener("click",function(){var country=findCountry(select.value)||current;storeSelectedCountry(country);trackSolarEvent("country_selected","country_picker",country?country.slug:DEFAULTS.countrySlug);});
}
function money(value){var n=Number(value)||0;return DEFAULTS.currencySymbol+n.toLocaleString("en-US",{maximumFractionDigits:0});}
function moneyAccessible(value){var n=Number(value)||0;return DEFAULTS.currency+" "+n.toLocaleString("en-US",{maximumFractionDigits:0});}
function years(value){return value&&Number.isFinite(value)?(value>=10?value.toFixed(0):value.toFixed(1))+" years":"No payback under these assumptions";}
function monthlyBatteryCost(kw,option){var profile=batteryProfiles[option]||batteryProfiles.essential;return option==="none"?0:DEFAULTS.batteryCost*(kw/3)*(profile.costFactor||1);}
var INSTALLER_CHECKLIST=["Confirm roof condition and shading.","Confirm panel wattage and warranty.","Confirm inverter type and surge capacity.","Confirm battery chemistry, usable kWh, depth of discharge, and warranty.","Confirm protection devices, earthing, and isolators.","Confirm installation price includes mounting, wiring, labour, and permits.","Confirm maintenance and after-sales support.","Confirm real energy consumption from bill or load profile.","Confirm financing total repayment.","Confirm payback assumptions."];
