};
function setFieldError(id,message){var el=byId(id);var error=byId(id+"Error");if(el){el.setAttribute("aria-invalid",message?"true":"false");}if(error)error.textContent=message||"";}
function validateInputs(focusFirst){
  var errors=[];
  Object.keys(FIELD_RULES).forEach(function(id){
    var rule=FIELD_RULES[id];var el=byId(id);if(!el)return;
    var value=parseFloat(el.value);var message="";
    if(!Number.isFinite(value)){message="Enter a number for "+rule.label.toLowerCase()+".";}
    else if(rule.min!=null&&value<rule.min){message=rule.message;}
    else if(rule.max!=null&&value>rule.max){message=rule.message;}
    setFieldError(id,message);
    if(message)errors.push({id:id,message:message});
  });
  var summary=byId("calcErrorSummary");
  if(errors.length){
    if(summary)summary.textContent=errors.length===1?errors[0].message:"Fix "+errors.length+" highlighted fields before using this estimate.";
    var status=byId("resultStatus");if(status)status.textContent="Fix highlighted inputs before results can update.";
    if(focusFirst){var first=byId(errors[0].id);var details=first&&first.closest?first.closest("details"):null;if(details)details.open=true;if(first&&first.focus)first.focus();}
    return false;
  }
  if(summary)summary.textContent="";
  return true;
}
function sponsorConfig(){var afro=window.AfroTools||{};return window.AfroToolsSolarRoiSponsors||(afro.sponsors&&afro.sponsors.solarRoi)||{};}
function trackSponsorSlot(eventName){trackSolarEvent(eventName);}
function renderSponsorSlots(){var config=sponsorConfig();Array.prototype.forEach.call(document.querySelectorAll("[data-sponsor-slot]"),function(slot){var slotId=slot.getAttribute("data-sponsor-slot");var item=config&&config[slotId]||config&&config.default;if(!item||item.enabled===false)return;var title=item.title||item.headline||"";var text=item.text||item.description||"";if(!title&&!text)return;var label=slot.querySelector("[data-sponsor-label]");var titleEl=slot.querySelector("[data-sponsor-title]");var textEl=slot.querySelector("[data-sponsor-text]");var link=slot.querySelector("[data-sponsor-link]");if(label)label.textContent=item.label||"Sponsored";if(titleEl)titleEl.textContent=title;if(textEl)textEl.textContent=text;if(link){link.textContent=item.cta||"Learn more";link.href=item.href||"/sponsored-tools/";link.hidden=false;}slot.hidden=false;slot.classList.add("is-configured");if(!slot.dataset.impressionTracked){slot.dataset.impressionTracked="true";trackSponsorSlot("sponsor_slot_impression",slotId);}if(link&&!link.dataset.bound){link.dataset.bound="true";link.addEventListener("click",function(){trackSponsorSlot("sponsor_slot_clicked",slotId);});}});}
function valueOrDash(value,suffix){return value||value===0?String(value)+(suffix||""):"--";}
function financeLabel(report){return report.financeEnabled?"Finance included: "+money(report.financeMonthlyPayment)+"/mo, "+money(report.totalInterest)+" interest":"Cash purchase in this estimate";}
function timelineRows(report){
  var years=[1,3,5,10,15,25];
  return years.map(function(year){
    var row=(report.cashflows||[])[year-1];
    return "Year "+year+": "+(row?money(row.cumulativeProjectCashflow):"--")+" cumulative, "+(row?money(row.projectNetCashflow):"--")+" annual cashflow";
  });
}
function buildReport(){
  if(!lastReport)return "";
  var r=lastReport;
  var rows=function(items){return items.map(function(item){return "<div><dt>"+esc(item[0])+"</dt><dd>"+esc(item[1])+"</dd></div>";}).join("");};
  var list=function(items){return "<ul class=\"solar-report-list\">"+items.map(function(item){return "<li>"+esc(item)+"</li>";}).join("")+"</ul>";};
  return "<div class=\"solar-report-header\"><h3>Solar ROI estimate for "+esc(r.countryName)+"</h3><p>Executive summary: "+esc(r.executiveSummary)+"</p></div>"+
    "<div class=\"solar-report-grid\">"+
    "<section class=\"solar-report-box\"><h4>User inputs</h4><dl class=\"solar-report-kv\">"+rows([["Monthly grid bill",r.monthlyBill],["Generator spend",r.generatorSpend+"/month"],["Outage hours",r.outageHours+" per day"],["System size",r.systemKw+" kW"],["Battery level",r.batteryLabel],["Finance",financeLabel(r)]])+"</dl></section>"+
    "<section class=\"solar-report-box\"><h4>Assumptions</h4><dl class=\"solar-report-kv\">"+rows([["Tariff",r.tariff],["Fuel price",r.fuelPrice],["Solar yield",r.solarYield],["Performance ratio",r.performanceRatio],["Install cost",r.installCostPerKw+"/kW"],["Maintenance",r.maintenancePct+"%/year"],["Source freshness",r.sourceFreshness],["Confidence",r.confidence]])+"</dl></section>"+
    "<section class=\"solar-report-box\"><h4>Results</h4><dl class=\"solar-report-kv\">"+rows([["System cost",r.systemCost],["Monthly savings",r.monthlySavings],["Payback",r.payback],["10-year net savings",r.tenYearNet],["25-year net savings",r.twentyFiveYearNet],["First-year generation",r.firstYearGeneration]])+"</dl></section>"+
    "<section class=\"solar-report-box\"><h4>Payback timeline</h4>"+list(timelineRows(r))+"</section>"+
    "<section class=\"solar-report-box\"><h4>Battery recommendation</h4>"+list([r.batteryRecommendation,"Usable capacity: "+r.batteryUsable,"Nominal estimate: "+r.batteryNominal,"Backup is for essential loads, not total daily energy."])+"</section>"+
    "<section class=\"solar-report-box\"><h4>Generator savings</h4><dl class=\"solar-report-kv\">"+rows([["Fuel avoided",r.generatorLitres],["Run-hours avoided",r.generatorHours],["Generator note",r.generatorNote]])+"</dl></section>"+
    "<section class=\"solar-report-box\"><h4>Roof and panels</h4><dl class=\"solar-report-kv\">"+rows([["Panel count",r.panelCount],["Panel wattage",r.panelWatt],["Roof area",r.roofArea],["Installer check","Inspect roof condition, shading, mounting clearance, and orientation before purchase."]])+"</dl></section>"+
    "<section class=\"solar-report-box\"><h4>Questions to ask installer</h4>"+list(INSTALLER_CHECKLIST)+"</section>"+
    "<section class=\"solar-report-box\"><h4>Disclaimers</h4>"+list(["This is a planning estimate, not a quote.","Replace defaults with written installer pricing, utility bills, fuel receipts, and lender terms.","PVGIS, Global Solar Atlas, or installer design software should be used for roof-level production modelling.","Sources last reviewed: "+r.sourceFreshness+". Confidence: "+r.confidence+"."])+"</section>"+
    "</div>";
}
