  var usable=result&&result.suggestedBatteryUsableKwh?result.suggestedBatteryUsableKwh:0;
  if(usable<=0)return "Battery not material for this load";
  if(option==="starter")return usable.toFixed(usable>=10?0:1)+" usable kWh starter backup";
  if(option==="extended")return usable.toFixed(usable>=10?0:1)+" usable kWh extended backup";
  return usable.toFixed(usable>=10?0:1)+" usable kWh essential backup";
