    avgSunHours:num("solarYield",DEFAULTS.solarYield),
    dailyLoadKwh:dailyKwh,
    peakLoadKw:Math.max(.3,Math.min(kw*1.35,dailyKwh/4)),
    backupHours:outageHours,
    monthlyElectricitySpend:monthlyBill,
