  set("rFuel",litresMonth.toFixed(litresMonth>=10?0:1)+" L/mo",(result.generatorRunHoursAvoided/12||0).toFixed(1)+" generator hours/month avoided.",litresMonth.toFixed(litresMonth>=10?0:1)+" litres per month");
  set("rRisk",decision.label,confidenceText(result.simplePaybackYears),decision.label);
