function run(focusFirstInvalid,source){
  if(!engine){byId("resultStatus").textContent="Solar ROI engine could not load. Open the full Africa calculator as a fallback.";return;}
  if(!validateInputs(!!focusFirstInvalid))return;
  var kw=Math.max(.1,num("systemKW",3));
  var batteryOption=val("batteryOption")||"essential";
  var batteryCost=monthlyBatteryCost(kw,batteryOption);
  var maintenancePct=num("maintenancePct",2.5);
  var includeFinance=val("financeEnabled")==="finance";
  var panelWatt=num("panelWatt",550);
  var batteryDodPct=num("batteryDodPct",80);
  var tariff=Math.max(.0001,num("tariffPerKwh",DEFAULTS.tariff));
  var monthlyBill=Math.max(0,num("monthlyBill",0));
  var outageHours=Math.max(0,Math.min(24,num("outageHours",0)));
  var dailyKwh=monthlyBill>0?monthlyBill/tariff/30:kw*DEFAULTS.solarYield*DEFAULTS.performanceRatio*.55;
  var inputs={
    systemKw:kw,
    avgSunHours:num("solarYield",DEFAULTS.solarYield),
    dailyLoadKwh:dailyKwh,
    peakLoadKw:Math.max(.3,Math.min(kw*1.35,dailyKwh/4)),
    backupHours:outageHours,
    monthlyElectricitySpend:monthlyBill,
    monthlyGeneratorFuelSpend:Math.max(0,num("generatorSpend",0)),
    outageHoursPerDay:outageHours,
    tariffPerKwh:tariff,
    fuelPricePerLitre:Math.max(0,num("fuelPrice",DEFAULTS.fuelPrice)),
    fuelBaselinePerLitre:Math.max(1,num("fuelPrice",DEFAULTS.fuelPrice)),
    installCostPerKw:Math.max(0,num("installCostPerKw",DEFAULTS.installCostPerKw)),
    batteryCostTotal:batteryCost,
    annualMaintenancePct:maintenancePct,
    systemEfficiencyPct:Math.max(1,Math.min(95,num("performanceRatio",DEFAULTS.performanceRatio)*100)),
    panelWatt:panelWatt,
    batteryDepthPct:batteryDodPct,
    batteryProfile:batteryOption,
    includeFinancing:includeFinance,
    depositPct:num("depositPct",20),
    annualInterestRatePct:num("interestPct",24),
    loanTermMonths:num("loanMonths",36),
    gridEmissionKgPerKwh:DEFAULTS.co2Factor
  };
  var result=engine.calculate(inputs);
  var monthlyGross=(result.firstYearGrossSavings||0)/12;
  var monthlyMaintenance=(result.systemCost||0)*(maintenancePct/100)/12;
  var monthlyNet=monthlyGross-monthlyMaintenance-(includeFinance?(result.finance.monthlyPayment||0):0);
  var litresMonth=(result.generatorLitresAvoided||0)/12;
  var profile=batteryProfiles[batteryOption]||batteryProfiles.essential;
  var decision=engine.decisionEngine({
    paybackYears:result.simplePaybackYears,
    outageHoursPerDay:inputs.outageHoursPerDay,
    monthlyGeneratorFuelSpend:inputs.monthlyGeneratorFuelSpend,
    monthlyElectricitySpend:inputs.monthlyElectricitySpend,
    financeMensuelPayment:includeFinance?result.finance.monthlyPayment:0,
    netMensuelAfterMaintenance:monthlyNet,
    batteryNeed:profile.label,
    systemAffordability:monthlyNet<0?"high pressure":"manageable",
    fuelAvoidedLitresPerMonth:litresMonth
  });
  var batteryLabel=(profile&&profile.label)||batteryOption;
  var backupFit=batteryOption==="none"?"No battery selected; generator or grid still covers outages.":"Selected battery should be checked against essential load and outage hours.";
  lastReport={
    countryName:DEFAULTS.countryName,
    countrySlug:DEFAULTS.countrySlug,
    confidence:DEFAULTS.confidence,
    sourceFreshness:DEFAULTS.lastReviewed,
    executiveSummary:decision.headline+" "+decision.reasons.slice(0,2).join(" "),
    systemKw:kw,
    monthlyBill:money(monthlyBill),
    generatorSpend:money(inputs.monthlyGeneratorFuelSpend),
    outageHours:outageHours,
    batteryLabel:batteryLabel,
    financeEnabled:includeFinance,
    financeMensuelPayment:result.finance.monthlyPayment||0,
    totalInterest:result.finance.totalInterestPaid||0,
    tariff:tariff+" "+DEFAULTS.currency+"/kWh",
    fuelPrice:inputs.fuelPricePerLitre+" "+DEFAULTS.currency+"/litre",
    solarYield:inputs.avgSunHours+" heures de soleil utiles par jour",
    performanceRatio:(inputs.systemEfficiencyPct||0).toFixed(1)+"%",
    installCostPerKw:money(inputs.installCostPerKw),
    maintenancePct:maintenancePct,
    systemCost:money(result.systemCost),
    monthlySavings:money(monthlyNet)+"/month",
    payback:years(result.simplePaybackYears),
    paybackYearsRaw:result.simplePaybackYears,
    tenYearNet:money(result.tenYearNetSavings),
    twentyFiveYearNet:money(result.twentyFiveYearNetSavings),
    firstYearGeneration:Math.round(result.firstYearGenerationKwh).toLocaleString("en-US")+" kWh",
